mapper.select:
select max( tam.id ) ID, tam.mix_area mix_area, tam.material_name material_name, listagg ( tlm.MACHINE_NAME, ',' ) within GROUP ( ORDER BY tam.machine_order ) AS MACHINE_NAME, listagg ( tam.MACHINE_CODE, ',' ) within GROUP ( ORDER BY tam.machine_order ) AS MACHINE_CODE, listagg ( tam.machine_order, ',' ) within GROUP ( ORDER BY tam.machine_order ) AS MACHINE_ORDER, max( tam.remark ) remark, max( tam.del_flag ) del_flag, max( tam.create_by ) create_by, max( tam.create_time ) create_time, max( tam.update_by ) update_by, max( tam.update_time ) update_time from t_accessories_machine tam inner join (select mix_area, machine_code, machine_name from t_mix_machine where del_flag = '0' union select mix_area, machine_code, machine_name from t_lhfl_machine where del_flag = '0') tlm on tam.MIX_AREA=tlm.MIX_AREA and tam.MACHINE_CODE=tlm.machine_code where tam.del_flag = '0' and tam.mix_area = #{mixArea} and INSTR(tam.material_name, #{materialName}) > 0 group by tam.MIX_AREA,tam.material_name
order by create_time desc
order by ${orderStr}

mapper.delete:
merge into t_accessories_machine a USING ( select mix_area,material_name from t_accessories_machine where id in
#{id, jdbcType=DOUBLE}
) b ON ( a.mix_area = b.mix_area and a.material_name = b.material_name ) WHEN MATCHED THEN UPDATE
a.del_flag='1'

delete from T_ACCESSORIES_MACHINE
where del_flag = '0'
  and mix_area = #{mixArea,jdbcType=VARCHAR}
  AND material_name = #{materialName,jdbcType=VARCHAR}

delete from T_ACCESSORIES_MACHINE where id in( select id from T_ACCESSORIES_MACHINE a, (
select #{item.mixArea,jdbcType=VARCHAR } mix_area, #{item.materialName,jdbcType=VARCHAR } material_name
) b where a.del_flag='0' and a.mix_area=b.mix_area and a.material_name=b.material_name )

mapper.insert:
insert into t_accessories_machine (id,mix_area,material_name,machine_code,machine_order,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{accessoriesMachine.mixArea,jdbcType= VARCHAR} mix_area, #{accessoriesMachine.materialName,jdbcType= VARCHAR} material_name, #{accessoriesMachine.machineCode,jdbcType= VARCHAR} machine_code, #{accessoriesMachine.machineOrder,jdbcType=VARCHAR} machine_order, #{accessoriesMachine.remark,jdbcType= VARCHAR} remark, #{accessoriesMachine.delFlag,jdbcType= VARCHAR} del_flag, #{accessoriesMachine.createBy,jdbcType= VARCHAR} create_by, #{accessoriesMachine.createTime,jdbcType=TIMESTAMP} create_time, #{accessoriesMachine.updateBy,jdbcType= VARCHAR} update_by, #{accessoriesMachine.updateTime,jdbcType=TIMESTAMP} update_time
) x

mapper.select:
select distinct tam.mix_area mix_area, tam.material_name material_name, tam.MACHINE_ORDER, tlm.MACHINE_NAME, tlm.MACHINE_CODE, ifnull(mcr.class_shift, tlm.class_shift) as now_class_shift, tlm.class_shift from t_accessories_machine tam inner join (select mix_area, machine_code, machine_name, null class_shift from t_mix_machine where del_flag = '0' and status = '0' union select mix_area, machine_code, machine_name, class_shift from t_lhfl_machine where del_flag = '0' and status = '0') tlm on tam.MIX_AREA=tlm.MIX_AREA and tam.MACHINE_CODE=tlm.MACHINE_CODE
left join (SELECT machine_code, max(class_shift) class_shift FROM t_material_schedule_result where schedule_date = to_date('2022-07-20', 'yyyy-mm-dd') group by machine_code) mcr on tam.machine_code = mcr.machine_code
where tam.del_flag = '0' and tam.mix_area = #{mixArea} and tam.material_name = #{materialName}
